import directory from './subjectDirectory.json' with {type:'json'};
export const CURRICULUM_KEY='aster-curriculum-v1';
export const OFFICIAL={IGCSE:'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-upper-secondary/cambridge-igcse/subjects/',IB:'https://ibo.org/programmes/diploma-programme/curriculum/'};
// Original Learnify learning guides. Topic groupings are study pathways, not copied syllabuses.
const units={};
function unit(id,title,concept,example,q,options,a,why,level='All'){units[id]={id,title,concept,example,q,options,a,why,level};return id;}
unit('number','Number, percentages & proportionality','A percentage expresses a quantity per hundred. A percentage change uses the original quantity as its denominator. Ratio compares quantities using a shared scale; direct proportion means one quantity is a constant multiple of the other.','A price of €80 rises by 15%: 80 × 1.15 = €92. A later 15% decrease gives 92 × 0.85 = €78.20, so equal percentage increases and decreases do not cancel.','A €60 item is reduced by 20%. What is the new price?',['€48','€40','€52','€72'],0,'Twenty percent of 60 is 12. Subtract 12 from the original 60.');
unit('algebra','Algebra & equations','An equation is a balance: applying the same valid operation to both sides preserves equality. Expand brackets before collecting like terms. When multiplying or dividing an inequality by a negative number, reverse the inequality sign.','Solve 3(x − 2) = 15: divide by 3 to obtain x − 2 = 5, then add 2 to obtain x = 7. Substitution into the original equation checks the result.','Solve 2x + 7 = 19.',['x = 5','x = 6','x = 12','x = 13'],1,'Subtract 7 to get 2x = 12; divide by 2 to get x = 6.');
unit('quadratics','Quadratics & completing the square','A quadratic contains a non-zero x² term. Factoring, completing the square, and the quadratic formula offer different routes to its roots. Vertex form a(x − h)² + k makes the turning point (h, k) visible.','x² + 6x + 5 = (x + 3)² − 4. The vertex is (−3, −4), and the roots are −1 and −5.','What is the vertex of y = (x − 2)² + 3?',['(−2, 3)','(2, −3)','(2, 3)','(3, 2)'],2,'In vertex form, h = 2 and k = 3. The square is zero when x = 2.');
unit('functions','Functions & transformations','A function assigns exactly one output to each input in its domain. f(x) + k shifts a graph vertically, while f(x − h) shifts it right by h. An inverse reverses a one-to-one mapping; restricting the domain may be necessary.','For f(x) = 2x + 3, write y = 2x + 3 and rearrange to x = (y − 3)/2. Thus f⁻¹(x) = (x − 3)/2.','What does y = f(x − 4) do to the graph of y = f(x)?',['Moves it left 4','Moves it right 4','Moves it up 4','Stretches it by 4'],1,'The same output now occurs when the input is 4 larger.');
unit('geometry','Geometry & similarity','Congruent shapes have equal corresponding sides and angles. Similar shapes preserve angles and have a constant scale factor for corresponding lengths. Areas scale with the square of that factor; volumes scale with its cube.','A similar solid is enlarged by a length factor of 3. Its surface area becomes 9 times as large and its volume becomes 27 times as large.','A rectangle is enlarged by factor 2.5. Its area is multiplied by…',['2.5','5','6.25','15.625'],2,'Area uses two dimensions, so the factor is 2.5² = 6.25.');
unit('trigonometry','Trigonometry','In a right triangle, sine, cosine, and tangent compare pairs of sides relative to an angle. Always identify the hypotenuse first and check whether your calculator uses degrees or radians. The sine and cosine rules extend calculations to non-right triangles.','If the hypotenuse is 10 cm and an angle is 30°, the opposite side is 10 sin 30° = 5 cm.','Which ratio equals tan θ in a right triangle?',['Adjacent / hypotenuse','Opposite / adjacent','Opposite / hypotenuse','Hypotenuse / adjacent'],1,'Tangent compares the opposite side with the adjacent side.');
unit('statistics','Statistics & data interpretation','The mean uses every value and can be influenced by extreme observations. The median is the middle of ordered data. Spread describes variability; always consider the sample and collection method before drawing conclusions about a population.','For 2, 3, 3, 4, 18, the mean is 6 but the median is 3. The unusually large observation pulls the mean upward.','Which summary is usually less affected by a single extreme outlier?',['Mean','Median','Range','Maximum'],1,'The median depends on position in the ordered data, not the size of an extreme value.');
unit('probability','Probability & conditional reasoning','For independent events, multiply probabilities to find the probability of both. For mutually exclusive events, add probabilities to find the probability of either. Conditional probability restricts attention to outcomes where the condition holds.','A bag has 3 red and 2 blue counters. Without replacement, P(two red) = (3/5)(2/4) = 3/10. The second probability changes after the first draw.','A fair coin is tossed twice. What is P(two heads)?',['1/2','1/3','1/4','3/4'],2,'The independent outcomes each have probability 1/2, giving 1/2 × 1/2 = 1/4.');
unit('differentiation','Differentiation & rates of change','A derivative measures an instantaneous rate of change and gives the gradient of a tangent. For a power xⁿ, the derivative is nxⁿ⁻¹. Stationary points satisfy f′(x) = 0, but additional analysis determines whether they are maxima, minima, or neither.','If s(t) = t³ − 3t, velocity is v(t) = 3t² − 3. At t = 2, the velocity is 9 distance units per time unit.','Differentiate f(x) = 4x³.',['12x²','4x²','12x³','x⁴'],0,'Apply the power rule: multiply by 3 and lower the power by 1.');
unit('integration','Integration & accumulation','An indefinite integral gives a family of antiderivatives, so include an arbitrary constant. A definite integral measures signed accumulation over an interval. Area below the horizontal axis contributes negatively to a signed integral.','∫₂⁴ 3x² dx = [x³]₂⁴ = 64 − 8 = 56. Evaluate at the upper limit, then subtract the value at the lower limit.','What is ∫ 2x dx?',['2x² + C','x² + C','x + C','2 + C'],1,'Differentiating x² gives 2x; the constant disappears under differentiation.');
unit('sequences','Sequences, series & financial models','An arithmetic sequence adds a constant difference; a geometric sequence multiplies by a constant ratio. Compound growth is geometric when the percentage rate is fixed. A model should state assumptions about rates and the time period.','€500 growing by 4% each year becomes 500(1.04)³ after three years. Do not round intermediate values unnecessarily.','Which sequence is geometric?',['2, 4, 6, 8','3, 6, 12, 24','1, 4, 9, 16','7, 7, 8, 8'],1,'Each term is twice the previous one. The common ratio is 2.');
unit('vectors','Vectors & mathematical modelling','A vector has magnitude and direction. Add vectors by adding corresponding components. The scalar product links algebraic components with the angle between vectors and can test perpendicularity.','For a = (2, 3) and b = (4, −1), a · b = 2×4 + 3×(−1) = 5. Their sum is (6, 2).','Vectors (1, 2) and (2, −1) are…',['Parallel','Perpendicular','Equal','Both unit vectors'],1,'Their dot product is 1×2 + 2×(−1) = 0, so they are perpendicular.');
unit('complex','Complex numbers & proof','Complex numbers extend real numbers by introducing i, with i² = −1. Algebraic and polar forms describe the same number. Mathematical proof establishes a claim for all allowed cases rather than checking only a few examples.','(2 + i)(2 − i) = 4 − i² = 5. Multiplying conjugates produces a real number.','What is i⁴?',['−1','0','1','i'],2,'i⁴ = (i²)² = (−1)² = 1.','HL extension');
unit('modelling','Regression & evaluating models','A mathematical model simplifies a real situation using assumptions. Regression describes an association in observed data; it does not establish a causal mechanism. Predictions far outside the data range are especially uncertain.','A line fitted to study times between 1 and 8 hours should not automatically be trusted to predict a result for 60 hours. The relationship may stop being linear.','Predicting beyond the observed data range is called…',['Interpolation','Extrapolation','Randomisation','Standardisation'],1,'Extrapolation extends a model outside the range in which it was fitted.');
unit('cells','Cells & membrane transport','Cells are the basic units of living organisms. The cell membrane regulates movement of substances. Diffusion is net movement down a concentration gradient; active transport uses energy to move substances against such a gradient.','Oxygen can diffuse into a respiring cell when its concentration is higher outside. A root hair cell may use active transport to absorb mineral ions against a gradient.','Which process requires an energy supply to move substances against a concentration gradient?',['Diffusion','Osmosis','Active transport','Evaporation'],2,'Active transport uses energy, often supplied by ATP.');
unit('enzymes','Enzymes & biological reactions','Enzymes catalyse reactions by lowering activation energy. Their active sites interact with particular substrates. Temperature and pH can change activity; sufficiently disruptive conditions alter protein structure and reduce function.','Heating an enzyme initially increases collision frequency. Above an appropriate range, structural changes reduce the number of functional active sites.','Why can very high temperatures reduce enzyme activity?',['Enzymes become substrates','The active site can change shape','All molecules stop moving','Activation energy becomes zero'],1,'Denaturation can change the active site so the substrate no longer binds effectively.');
unit('photosynthesis','Photosynthesis & respiration','Photosynthesis transfers light energy into chemical stores, using carbon dioxide and water to build carbohydrates. Aerobic respiration releases usable energy from organic molecules using oxygen. Plants respire as well as photosynthesise.','A plant kept in darkness cannot sustain photosynthesis, but living cells continue to respire using stored compounds while supplies last.','Most of the carbon in a plant’s newly made glucose comes from…',['Soil minerals','Carbon dioxide','Water','Sunlight'],1,'Carbon dioxide supplies carbon atoms. Light provides energy rather than matter.');
unit('genetics','Inheritance, DNA & variation','DNA stores genetic information in a sequence of bases. Alleles are alternative versions of a gene. An organism’s characteristics result from genetic and environmental influences; simple dominant/recessive models describe only some patterns of inheritance.','In a cross Aa × Aa with complete dominance, the genotype probabilities are 1/4 AA, 1/2 Aa, and 1/4 aa.','For Aa × Aa, what is the probability of genotype aa?',['0','1/4','1/2','3/4'],1,'The four equally likely combinations are AA, Aa, aA, and aa.');
unit('ecology','Ecology & ecosystems','Energy enters most ecosystems through photosynthesis and moves through feeding relationships. Energy is dissipated at every trophic transfer, while matter cycles between organisms and the environment. Sampling methods must match the organisms and the question being investigated.','Quadrats can estimate abundance of plants. Random placement reduces selection bias; repeated samples show variation and improve the estimate.','Which method best reduces bias in sampling stationary plants?',['Place quadrats only near paths','Choose the greenest patches','Use random quadrat locations','Count one convenient plant'],2,'Random locations avoid deliberately favouring certain parts of the habitat.');
unit('evolution','Evolution & natural selection','Populations contain heritable variation. If a trait improves reproductive success in a particular environment, the alleles associated with it may become more frequent over generations. Natural selection acts on existing variation; it does not give individuals traits because they need them.','An antibiotic can leave resistant bacteria more likely to survive and reproduce. The drug does not intentionally train individual bacteria to become resistant.','Natural selection directly depends on differences in…',['Reproductive success','An organism’s wishes','The age of the Earth','Uniformity of all individuals'],0,'Heritable traits become more common when their carriers leave more surviving offspring.');
unit('homeostasis','Homeostasis & human physiology','Homeostasis maintains internal conditions within ranges compatible with life. Negative feedback detects deviations and activates responses that oppose them. Regulation often involves coordination among receptors, a processing centre, and effectors.','When body temperature rises, increased skin blood flow and sweating can increase heat loss. The response decreases as temperature returns toward its regulated range.','Negative feedback usually…',['Amplifies any change indefinitely','Opposes a deviation from a regulated range','Prevents all variation','Works without receptors'],1,'A negative feedback response counteracts the change that triggered it.');
unit('atomic','Atomic structure & the periodic table','Atoms contain a nucleus with protons and usually neutrons, surrounded by electrons. Atomic number counts protons; mass number counts protons plus neutrons. Isotopes have the same number of protons but different numbers of neutrons.','Carbon-12 and carbon-14 both have 6 protons. They have 6 and 8 neutrons respectively. Their chemical similarities follow from their electron arrangements.','Two isotopes of an element differ in their number of…',['Protons','Neutrons','Atomic numbers','Nuclear charges'],1,'Their proton numbers identify the same element, while their neutron numbers differ.');
unit('bonding','Bonding, structure & properties','Ionic bonding is electrostatic attraction between oppositely charged ions. Covalent bonding involves shared electron pairs. Material properties depend on the structure as well as the type of bond, so molecular substances and giant covalent structures behave differently.','Solid sodium chloride has ions fixed in a lattice. When molten, ions can move and carry electric charge.','Why does molten sodium chloride conduct electricity?',['Its atoms become neutral','Its ions can move','Its protons leave the nuclei','It contains freely moving molecules only'],1,'Mobile charged ions carry current through the liquid.');
unit('moles','Chemical quantities & stoichiometry','The mole is a counting unit. Amount in moles equals mass divided by molar mass. A balanced equation gives mole ratios, which allow you to identify the limiting reactant and calculate theoretical product amounts.','For 2H₂ + O₂ → 2H₂O, 2 mol of hydrogen require 1 mol of oxygen. If 3 mol H₂ and 1 mol O₂ are available, oxygen limits the reaction.','How many moles are in 18 g of water, with molar mass 18 g mol⁻¹?',['0.5 mol','1 mol','18 mol','324 mol'],1,'n = m/M = 18/18 = 1 mol.');
unit('energetics','Energy changes & reaction rates','Breaking bonds requires energy and forming bonds releases energy. Exothermic reactions transfer energy to the surroundings; endothermic reactions absorb it. A catalyst changes reaction rate by providing a pathway with lower activation energy.','A catalyst helps a reaction reach equilibrium sooner but does not change the equilibrium position or the overall enthalpy change.','A catalyst works mainly by…',['Raising activation energy','Lowering activation energy','Changing the atoms into other elements','Making every reaction exothermic'],1,'It provides an alternative reaction pathway with a lower energy barrier.');
unit('acids','Acids, bases & equilibria','In aqueous solutions, acids increase hydrogen ion concentration and bases accept protons or produce hydroxide ions. Strong and weak describe extent of ionisation, while concentrated and dilute describe amount per volume. These are different distinctions.','A dilute strong acid may contain less hydrogen ion per litre than a sufficiently concentrated weak acid. Use actual concentrations and equilibria when comparing pH.','Which pair describes different ideas?',['Strong and concentrated','Dilute and low concentration','Acid and proton donor','Neutralisation and acid–base reaction'],0,'Strength refers to ionisation; concentration refers to amount per volume.');
unit('organic','Organic chemistry & functional groups','Carbon forms varied chains and rings. A functional group largely determines a compound’s characteristic reactions. Homologous series share a functional group and general chemical patterns, with successive members differing by CH₂.','Ethanol has an –OH functional group. Ethanoic acid contains –COOH, so the two compounds have different characteristic reactions.','Which functional group identifies a carboxylic acid?',['–OH','–COOH','C=C','–NH₂'],1,'The carboxyl group is –COOH.');
unit('redox','Redox & electrochemistry','Oxidation is loss of electrons and reduction is gain of electrons. They occur together because electrons transfer between species. Half-equations track atoms and charge separately before being combined.','Zn → Zn²⁺ + 2e⁻ represents oxidation. The zinc atom loses two electrons and becomes a positively charged ion.','In Cu²⁺ + 2e⁻ → Cu, copper ions are…',['Oxidised','Reduced','Evaporated','Neutralised by a base'],1,'They gain electrons, which is reduction.');
unit('motion','Motion & forces','Velocity describes the rate of change of displacement; acceleration describes the rate of change of velocity. The resultant force equals mass times acceleration in the usual constant-mass model. Zero resultant force means constant velocity, which may be zero or non-zero.','A 2 kg object accelerating at 3 m s⁻² has a resultant force of 6 N. Forces may still act on an object moving at constant velocity, but they balance.','An object moves at constant velocity. Its resultant force is…',['Zero','Increasing','Equal to its weight in every case','Always forward'],0,'There is no acceleration, so the resultant force is zero.');
unit('energy','Work, energy & power','Work transfers energy when a force acts through a displacement. Energy is conserved across a chosen system and its surroundings. Power is the rate of energy transfer, and efficiency compares useful output with total input.','A device transfers 600 J in 3 s. Its average power is 600/3 = 200 W.','A machine takes in 100 J and produces 75 J of useful output. Its efficiency is…',['25%','75%','100%','175%'],1,'Efficiency = useful output / input × 100% = 75%.');
unit('waves','Waves, light & sound','Waves transfer energy without a net transfer of matter across the whole distance. Wave speed equals frequency times wavelength. Reflection, refraction, diffraction, and interference describe different behaviours of waves.','A wave with frequency 50 Hz and wavelength 4 m travels at 200 m s⁻¹. In a new medium, frequency remains fixed by the source while speed and wavelength can change.','For a wave, speed equals…',['Frequency / wavelength','Wavelength / frequency','Frequency × wavelength','Amplitude × frequency'],2,'v = fλ. The units are s⁻¹ × m = m s⁻¹.');
unit('electricity','Electric circuits','Current is the rate of flow of charge. Potential difference measures energy transferred per unit charge. In a series circuit current is the same throughout; parallel branches share the potential difference across their common endpoints.','A 6 Ω resistor with 12 V across it carries 2 A if it obeys Ohm’s law. The power is VI = 24 W.','Two branches connected in parallel have the same…',['Current in every case','Potential difference','Resistance in every case','Number of electrons'],1,'Each branch connects the same pair of circuit nodes.');
unit('thermal','Thermal physics & particles','Temperature relates to the average kinetic energy of particles. Internal energy includes kinetic and potential contributions. A change of state can transfer energy without changing temperature because particle arrangements and interactions change.','When pure ice melts at a fixed pressure, energy can increase internal energy while the temperature remains at the melting point.','During melting at constant pressure, supplied energy mainly…',['Always increases temperature','Changes particle interactions and arrangement','Destroys the particles','Removes all internal energy'],1,'Energy is associated with the phase change rather than a temperature increase.');
unit('fields','Fields, gravitation & magnetism','A field describes the force that would act on an appropriate test object at each point. Gravitational fields act on mass; electric fields act on charge. Field lines represent direction and relative strength, rather than physical strings.','The gravitational force between point masses varies inversely with the square of their separation. Doubling the separation reduces the force to one quarter.','If the distance between two point masses doubles, their gravitational force becomes…',['Twice as large','Half as large','One quarter as large','Four times as large'],2,'The inverse-square factor is 1/2² = 1/4.');
unit('nuclear','Atomic & nuclear physics','Radioactive decay is a random process for an individual unstable nucleus. Half-life describes the time for the expected number of undecayed nuclei in a large sample to halve. Activity measures decays per unit time.','After three half-lives, the expected undecayed fraction is (1/2)³ = 1/8. This is a statistical prediction for a large sample.','What fraction remains after two half-lives?',['1/2','1/4','1/8','0'],1,'The sample halves twice: 1 × 1/2 × 1/2 = 1/4.');
unit('algorithms','Algorithms & computational thinking','An algorithm is a precise sequence of steps for solving a class of problems. Decomposition breaks a problem into parts; abstraction focuses on relevant details. Trace tables help test a process before it is implemented.','To find the largest number in a non-empty list, store the first value, compare each remaining value with the stored maximum, and replace the maximum when a larger value appears.','Why initialise a maximum to the first item instead of zero?',['Zero is never allowed in programming','All values could be negative','It sorts the list automatically','It avoids every comparison'],1,'If all values are negative, a maximum initially set to zero may incorrectly stay zero.');
unit('programming','Programming & data structures','Variables hold values, selection chooses branches, and iteration repeats steps. Functions divide a program into reusable operations. Choose data structures according to the operations needed, and test normal, boundary, and invalid inputs.','A function that averages a list must handle the empty-list case before dividing by its length. Checking only a typical positive-number list misses this boundary.','Which is a useful boundary test for a list-average function?',['Only a large random list','An empty list','Only a list of five positive values','A screenshot of the code'],1,'An empty list exposes a possible division by zero or undefined result.');
unit('binary','Data representation & computer systems','Binary represents values using powers of two. Text, images, and sound need agreed encodings to be stored digitally. File size depends on representation choices; compression trades off size, processing, and sometimes fidelity.','Binary 1011₂ = 1×8 + 0×4 + 1×2 + 1×1 = 11₁₀.','What is binary 1101 in decimal?',['11','12','13','14'],2,'8 + 4 + 0 + 1 = 13.');
unit('networks','Networks, security & digital responsibility','Networks allow devices to exchange data using protocols. Encryption protects confidentiality; authentication checks identity. A secure system also needs access control, updates, backups, and thoughtful handling of personal data.','A password manager can generate distinct passwords so a breach of one website does not automatically expose accounts elsewhere.','Which control primarily verifies who a user is?',['Compression','Authentication','Caching','Sorting'],1,'Authentication verifies identity; authorisation decides what that identity may access.');
unit('databases','Databases & information systems','Relational databases store related data in tables. A primary key uniquely identifies a row; a foreign key relates it to another table. Good design reduces unnecessary duplication and supports consistency.','A students table stores each student once. An enrolments table connects student IDs to course IDs, supporting many students in many courses.','What is the main purpose of a primary key?',['Encrypt every cell','Uniquely identify a row','Sort all text alphabetically','Replace every foreign key'],1,'A primary key is a unique identifier for a table’s records.');
unit('text','Reading, inference & textual evidence','Reading analytically means distinguishing what a text states from what you infer. Support interpretations with carefully selected details. A convincing inference explains how the evidence leads to the claim while allowing for ambiguity.','If a narrator repeatedly avoids naming a visitor, you might infer anxiety or secrecy. Explain the pattern and consider whether another reading fits the same evidence.','Which response offers the strongest analytical support?',['The text is good','The narrator seems worried because repeated pauses interrupt the greeting','It is probably about everything','The writer uses words'],1,'It identifies a claim, a specific feature, and a link between them.');
unit('analysis','Language, structure & effect','Writers make choices about diction, syntax, imagery, voice, and structure. Analysis connects those choices to meaning and context. Naming a technique is a starting point, not an explanation of its effect.','A short sentence after a long descriptive paragraph can interrupt the rhythm and draw attention to a decisive action. The effect depends on the surrounding passage.','After identifying a metaphor, your next step should be to…',['List unrelated techniques','Explain its meaning and effect in context','Retell the whole plot','Assume every reader feels the same'],1,'Analysis explains how the choice shapes meaning in that particular text.');
unit('argument','Writing an argument','A defensible argument has a focused claim, relevant evidence, and reasoning linking them. Addressing a plausible counterargument can clarify the limits of your position. Paragraph order should guide the reader through a developing line of thought.','Claim: the ending is deliberately unresolved. Evidence: the final question is unanswered. Reasoning: the reader must weigh competing interpretations rather than accept a single outcome.','Which part explains why evidence supports the claim?',['A decorative heading','Reasoning','A longer quotation alone','A repeated thesis'],1,'Reasoning makes the logical connection between evidence and conclusion.');
unit('comparison','Comparative literature & perspectives','A comparison should organise ideas around meaningful similarities and differences. Consider how genre, context, voice, and form affect treatment of a shared concern. Move between works within an argument instead of writing two disconnected summaries.','Compare how two texts depict belonging: one may use an intimate first-person voice, while another uses a fragmented chorus. Discuss what each approach enables the reader to understand.','A strong comparative paragraph is usually organised around…',['A shared analytical idea','The longer book only','Unconnected plot summaries','A list of publication dates'],0,'A common analytical focus lets differences and similarities contribute to the argument.');
unit('language','Language acquisition & retrieval','Language learning combines understanding messages with producing them. Retrieval practice strengthens access to vocabulary, and spaced review revisits words before they are forgotten. Learn words in useful phrases so grammar and meaning stay connected.','Instead of memorising only a word for transport, practise a sentence about how you travel to school, then change the subject, tense, or reason.','Which practice most directly tests active recall?',['Looking at a word list again','Producing a phrase from a meaning prompt','Highlighting every word','Copying a paragraph without thinking'],1,'Producing the phrase requires retrieving it from memory.');
unit('listening','Listening & speaking strategies','Listen first for purpose and overall meaning, then for specific details. In speaking, communicate a clear idea and build it with reasons or examples. Repairing a misunderstanding is a useful communication skill, not a failure.','If you miss a time in an announcement, use the surrounding context and listen for repetition. In conversation, ask the speaker to repeat or clarify rather than guessing silently.','If you do not understand an important detail in conversation, the best next step is to…',['Pretend you understood','Ask for clarification','Change every topic','Stop speaking permanently'],1,'Clarification helps both speakers establish the intended meaning.');
unit('grammar','Grammar, register & purposeful writing','Grammar expresses relationships such as time, possibility, cause, and emphasis. Register adapts language to audience and situation. A clear message uses forms appropriate to its purpose, then checks agreement, word order, and consistency.','An email to a friend and a formal request can convey the same basic information, but their greetings, vocabulary, and closing phrases will differ.','Register is most closely related to…',['Only the length of a text','Language choices for audience and situation','The number of pages','Always using the longest words'],1,'Register reflects the social context and intended reader or listener.');
unit('microeconomics','Scarcity, markets & elasticity','Scarcity means resources are limited relative to wants, so choices involve opportunity cost. Demand and supply models describe how buyers and sellers respond under stated assumptions. Elasticity measures responsiveness using percentage changes.','If quantity demanded falls by 20% after a 10% price rise, the magnitude of price elasticity of demand is 2. Other influences are assumed unchanged.','Opportunity cost is the value of…',['Every possible choice combined','The next best alternative forgone','Only money already spent','The cheapest available option'],1,'Choosing one option means giving up the best alternative you could otherwise have taken.');
unit('macroeconomics','Growth, inflation & unemployment','Macroeconomics studies aggregate outcomes such as output, employment, and the price level. Real measures adjust for price changes. Policy evaluation considers trade-offs, time lags, distribution, and the conditions under which a policy operates.','If nominal output rises 5% while prices rise approximately 3%, real output growth is about 2%; an exact calculation uses 1.05/1.03 − 1.','Why use real GDP when comparing output over time?',['It removes all inequality','It adjusts for price changes','It counts only exports','It ignores population and prices alike'],1,'Real GDP aims to separate changes in production from changes in the price level.');
unit('trade','Trade, development & global connections','Trade allows specialisation but its effects differ among workers, firms, and consumers. Development includes more than income: health, education, distribution, and environmental conditions matter. Compare indicators and examine their limitations.','Two countries with similar income per person may have different life expectancy or educational access. A single average cannot describe all lived experiences.','Which conclusion is best supported by a rise in GDP per person alone?',['Everyone is better off','Average measured output per person has increased','Inequality has disappeared','Environmental quality has improved'],1,'The average increases, but the statistic alone does not establish distribution or wider wellbeing.');
unit('business','Business objectives & stakeholders','Businesses combine resources to produce goods and services. Owners, workers, customers, suppliers, communities, and governments may have different objectives. A decision should be evaluated through its costs, benefits, risks, and consequences for stakeholders.','Automating a production line may lower unit costs and improve consistency, but it requires investment and may affect workers’ roles.','Who is a stakeholder?',['Only the chief executive','Any person or group affected by a business','Only someone owning shares','Only paying customers'],1,'Stakeholders include a broader range of affected groups than shareholders.');
unit('finance','Business finance & accounts','Revenue is income from sales, while profit subtracts relevant costs. Cash flow tracks actual receipts and payments; a profitable business may still run short of cash. Financial statements serve different purposes and must be interpreted in context.','A business sells goods on credit for a profit but pays suppliers immediately. It may face a cash shortage before customers pay.','Which statement is correct?',['Profit always equals cash in the bank','A profitable business can have cash-flow difficulties','Revenue is profit','A loan is always sales revenue'],1,'The timing of cash receipts and payments can differ from the recognition of revenue and costs.');
unit('accounting','Double entry & financial statements','Every recorded transaction has two corresponding accounting effects. Assets equal liabilities plus equity. The statement of financial position is a snapshot at a date; an income statement reports performance over a period.','Buying equipment for cash increases one asset, equipment, and decreases another asset, cash. Total assets can remain unchanged at the purchase date.','Buying equipment for cash immediately…',['Always increases total assets','Swaps one asset for another','Creates sales revenue','Always doubles equity'],1,'The increase in equipment is balanced by the decrease in cash.');
unit('marketing','Marketing, operations & human resources','Marketing identifies customer needs and communicates a suitable offer. Operations organise production and quality; human resources supports recruitment, development, and working relationships. Decisions across these functions affect one another.','A promotion that doubles demand may fail if production capacity cannot increase. Evaluate the whole system, not only the campaign.','Why should a promotion be coordinated with operations?',['Demand and capacity can affect delivery','Marketing never affects sales','Workers do not affect output','Every product has unlimited supply'],0,'The business must be able to fulfil the demand it creates.');
unit('history','Historical evidence & source evaluation','Historical arguments use evidence interpreted in context. Evaluate a source’s origin, purpose, content, and the question it can help answer. A biased source is not automatically useless: its perspective may itself be evidence.','A political speech may be weak evidence of opponents’ private motives but strong evidence of how the speaker tried to persuade an audience.','A source with an obvious political purpose is…',['Always worthless','Useful for some questions but requiring careful evaluation','Automatically accurate','Only useful if it agrees with your view'],1,'Utility depends on the historical question, the source’s content, and its limitations.');
unit('causation','Causation, change & historical argument','Historical explanations distinguish long-term conditions, short-term triggers, and decisions by individuals or groups. Causes can interact and vary in significance. A chronology establishes sequence but does not by itself explain why an event occurred.','An economic crisis may increase tensions while a political decision triggers a confrontation. Explain the mechanism connecting each factor to the outcome.','What turns a list of causes into an explanation?',['More dates alone','Showing how factors contributed and interacted','Repeating the event title','Assuming the earliest factor caused everything'],1,'Explanation identifies causal mechanisms and relationships.');
unit('geography','Population, settlement & spatial patterns','Geography studies the relationships between people, places, and environments. Population change reflects births, deaths, and migration. Spatial patterns need explanations involving scale, processes, and local context rather than description alone.','A city’s population may grow even when births and deaths balance if net migration is positive.','Population change equals…',['Births − deaths + net migration','Births + deaths','Only immigration','Births − immigration'],0,'Natural increase and net migration together determine the change.');
unit('physical','Physical geography & landscapes','Landscapes develop through interacting processes such as weathering, erosion, transport, and deposition. Distinguish the breakdown of material in place from its movement. Patterns also depend on geology, climate, time, and human activity.','A river deposits more of its carried sediment when flow conditions reduce its capacity to transport that sediment.','Which process breaks rock down in place?',['Transportation','Weathering','Deposition','Migration'],1,'Weathering breaks down rock where it is; erosion removes material.');
unit('climate','Climate, resources & sustainability','Weather describes short-term atmospheric conditions; climate describes patterns over longer periods. Sustainability requires considering ecological limits, social needs, and economic decisions. Evaluate proposed solutions using evidence, scale, and unintended effects.','A single cold day does not disprove a long-term warming trend. Compare appropriately collected records over sufficiently long periods.','Why is one day of weather insufficient to establish a climate trend?',['Weather measurements are never useful','Climate describes long-term patterns','Climate can never change','Only rainfall matters'],1,'Short-term variability must be distinguished from a sustained pattern.');
unit('fieldwork','Fieldwork & research methods','A useful investigation links a focused question to an appropriate sampling strategy and measurement method. Identify independent, dependent, and controlled variables where relevant. Reliability, validity, ethics, and uncertainty all affect the strength of conclusions.','To compare river velocity at sites, use a consistent method, repeat measurements, and record conditions. A wider sample supports a more defensible comparison.','Repeating measurements mainly helps you assess…',['Only the title','Variation and reliability','Whether a hypothesis must be true','The researcher’s popularity'],1,'Repeated observations reveal variation and help estimate a representative value.');
unit('psychology','Behaviour, cognition & research design','Psychology investigates behaviour and mental processes using systematic evidence. Experiments can test causal hypotheses by manipulating variables while controlling alternatives. Correlational studies describe associations but cannot alone establish causation.','A relationship between sleep duration and test scores does not prove sleep is the only cause. Stress, study habits, or health may influence both.','A correlation alone establishes…',['A causal mechanism','An association','That there are no confounding variables','A universal law'],1,'Further evidence is needed to determine causal direction and exclude alternative explanations.');
unit('society','Culture, identity & social institutions','Social research examines how individuals and institutions influence each other. Norms are shared expectations, while values concern what a group regards as important. Avoid treating a community as uniform or confusing an individual example with a population-wide pattern.','A school rule is a formal norm. Expectations about how students greet one another may be informal norms that vary across groups and situations.','A social norm is best described as…',['A shared expectation about behaviour','A gene','A universal personal preference','A measurement with no context'],0,'Norms guide what people consider expected or acceptable in a social setting.');
unit('politics','Power, rights & global politics','Political analysis studies power, legitimacy, institutions, and competing claims. Distinguish a descriptive statement about what happens from a normative claim about what should happen. Evaluate policy through evidence and more than one stakeholder perspective.','A policy may improve average outcomes while imposing substantial costs on a minority. Evaluation should identify both the overall effect and its distribution.','Which statement is normative?',['The vote took place on Monday','Turnout was 70%','The policy should be fairer','Three proposals were debated'],2,'It expresses a judgment about what ought to be, rather than only describing an observation.');
unit('philosophy','Philosophical arguments & knowledge','An argument offers premises intended to support a conclusion. Validity concerns whether the conclusion follows if the premises are true; soundness also requires true premises. Clarify concepts and test an argument against plausible counterexamples.','All mammals are animals; whales are mammals; therefore whales are animals. The logical structure supports the conclusion from the premises.','A valid argument…',['Must have true premises','Has a conclusion that follows if its premises are true','Must be popular','Cannot be written in words'],1,'Validity concerns the inference; soundness adds the requirement of true premises.');
unit('religion','Religious traditions & interpretation','Study a tradition through its texts, practices, histories, and the interpretations of its communities. Distinguish an insider account from an external analysis without assuming either perspective is uniform. Use accurate terms and acknowledge diversity within traditions.','Two communities sharing a sacred text may interpret or practise aspects differently because of historical, cultural, or theological contexts.','Why compare more than one account of a religious tradition?',['To assume all accounts are identical','To understand diversity and perspective','To rank believers','To avoid examining evidence'],1,'Multiple accounts help reveal variations in experience and interpretation.');
unit('art','Visual language & artistic inquiry','Artists organise elements such as line, colour, shape, space, and texture to construct meaning. Analyse what is visible before drawing interpretations. Experimentation and reflection connect research with practical decisions.','Changing a composition’s negative space can alter the balance and emphasis without changing its subject. Make a second version, then compare the effect.','Negative space refers to…',['Only black paint','Space around and between forms','A mistake in perspective','A work with no meaning'],1,'Negative space is the area surrounding and separating the main forms.');
unit('design','Design thinking & evaluation','A design process begins with an identified need and constraints. Research informs specifications; prototypes test possible solutions. Evaluation compares evidence with success criteria and leads to justified refinements.','A desk organiser designed for a small surface must be tested for dimensions, stability, accessibility, and usability with the intended user.','A useful design specification is…',['A vague wish for something nice','A measurable criterion tied to user needs','A colour chosen at random','Only a final photograph'],1,'Measurable criteria make testing and evaluation meaningful.');
unit('music','Musical elements & analysis','Music combines patterns of rhythm, melody, harmony, texture, timbre, and form. Describe what you hear with precise terms and relate features to their musical context. Performance and composition decisions can test an analytical interpretation.','A melody repeated with a different accompaniment may feel transformed even if the pitches remain unchanged. Listen for which element changes and explain its effect.','Timbre most closely describes…',['The quality or colour of a sound','Only its loudness','The number of bars','The speed of the pulse'],0,'Timbre distinguishes sound qualities, such as those of different instruments playing the same pitch.');
unit('performance','Theatre, dance & performance choices','Performance communicates through bodies, voices, space, timing, and relationships with an audience. Connect choices to an artistic intention. Rehearsal develops a performance through experimentation, feedback, and reflection.','A character delivering the same line from opposite sides of a space can change a scene’s power relationships. Compare choices and explain which supports your intention.','An effective rehearsal reflection should…',['Only say it went well','Link observed effects to specific choices and next steps','List costumes only','Avoid any changes'],1,'Reflection uses evidence to improve future performance decisions.');
unit('film','Film language & storytelling','Films construct meaning through framing, camera movement, editing, lighting, mise-en-scène, and sound. Analyse the relationship between a choice and its context rather than assigning every technique one fixed meaning.','A close-up after a wide shot may shift attention from a setting to a character’s reaction. The accompanying sound and sequence influence its interpretation.','Editing primarily concerns…',['Only camera manufacture','The selection and arrangement of shots','The actors’ contracts','The cinema’s seating'],1,'Editing shapes how shots relate in time, space, rhythm, and meaning.');
unit('sport','Movement, exercise & training','Physical activity depends on coordinated muscular, skeletal, cardiovascular, and respiratory systems. Training adaptations depend on load, recovery, specificity, and individual variation. Use evidence rather than assuming more intensity is always better.','A training plan for endurance differs from one focused on explosive strength. Both need appropriate recovery and progression.','The principle of specificity means training should…',['Be identical for everyone','Match the demands of the activity or goal','Avoid all recovery','Always last two hours'],1,'Adaptations are related to the type of training performed.');
unit('nutrition','Nutrition & food science','A balanced diet supplies energy and nutrients in appropriate amounts for individual needs. Food preparation and storage affect safety and quality. Evaluate nutritional claims by considering evidence, portions, and the whole dietary pattern.','A food described as low fat is not automatically low in sugar or appropriate for every dietary need. Read the wider nutritional information.','Why is one label claim insufficient to assess a food?',['Labels never contain facts','Other nutrients, portions, and context also matter','Only its colour matters','All foods have identical composition'],1,'A single characteristic does not describe the whole food or dietary pattern.');
unit('agriculture','Agriculture & food systems','Agricultural production depends on interactions among soil, water, organisms, climate, technology, and people. Soil management and biodiversity affect long-term productivity. Compare methods using yields, resource use, costs, and environmental effects.','A crop rotation can interrupt some pest cycles and change nutrient demands. Its suitability depends on the crops, soils, and farming context.','Why evaluate farming practices over more than one season?',['The first season never matters','Long-term soil and ecosystem effects may differ from immediate yields','All methods become identical','Weather never changes'],1,'Sustainable productivity involves effects that develop over time.');
unit('tourism','Tourism & destination management','Tourism connects visitors, businesses, residents, infrastructure, and environments. Its economic benefits may be unevenly distributed, while environmental and social costs depend on scale and management. Evaluate a destination through multiple stakeholder perspectives.','A busy attraction may create jobs while increasing traffic and pressure on local services. Management can change how benefits and costs are distributed.','Which is a stakeholder in tourism planning?',['Only overseas visitors','Local residents as well as visitors and businesses','Only hotel owners','Only travel agents'],1,'Residents experience many of the effects of tourism and belong in planning discussions.');
unit('research','Research questions & academic integrity','A focused research question is narrow enough to investigate with accessible evidence. Keep track of sources, distinguish quotation from paraphrase, and explain how evidence supports the argument. A bibliography alone does not replace accurate attribution within the work.','Instead of asking whether all transport is sustainable, investigate a defined route, period, and measure of impact using accessible data.','A useful research question should be…',['As broad as possible','Focused and answerable with suitable evidence','Guaranteed to prove your first opinion','Unrelated to available sources'],1,'A manageable question connects the inquiry to evidence you can actually analyse.');
unit('tok','Theory of knowledge & justification','TOK examines how knowledge claims are made, supported, and evaluated. Distinguish the claim, the evidence offered, and the assumptions that connect them. Compare perspectives and consider the strengths and limits of methods in different areas of knowledge.','A controlled experiment and a historical archive support claims in different ways. Ask which standards of evidence suit the question, rather than assuming one method answers everything.','A productive TOK discussion focuses on…',['Memorising one correct opinion','How claims are justified and what limits that justification','Ranking subjects by popularity','Avoiding examples'],1,'TOK develops critical reflection on knowledge and its justification.');
unit('cas','CAS planning & reflection','Creativity, activity, and service invite learning through purposeful experience. Set a meaningful intention, consider the needs of others, and reflect on what actually changed. Participation and reflection should be authentic rather than invented to fill a record.','After helping organise a community event, reflect on a difficult decision, how you responded, and what you would change in another project.','Which reflection is most useful?',['Everything was perfect','A specific challenge, response, and lesson for next time','A list of hours with no context','An invented success story'],1,'Specific reflection connects experience with learning and future action.');
export const UNITS=units;
const paths={
 maths:['number','algebra','quadratics','functions','geometry','trigonometry','statistics','probability'],additional:['algebra','quadratics','functions','trigonometry','sequences','vectors','differentiation','integration'],aa:['algebra','functions','sequences','trigonometry','vectors','probability','statistics','differentiation','integration','complex'],ai:['number','functions','sequences','geometry','trigonometry','statistics','probability','modelling','differentiation','integration'],statistics:['statistics','probability','modelling','fieldwork'],biology:['cells','enzymes','photosynthesis','genetics','ecology','evolution','homeostasis','fieldwork'],chemistry:['atomic','bonding','moles','energetics','acids','redox','organic','fieldwork'],physics:['motion','energy','thermal','waves','electricity','fields','nuclear','fieldwork'],science:['cells','photosynthesis','atomic','bonding','motion','energy','electricity','ecology','fieldwork'],computing:['algorithms','programming','binary','networks','databases','research'],ict:['binary','networks','databases','modelling','design','research'],english:['text','analysis','argument','comparison','grammar','research'],language:['language','listening','grammar','text','argument'],literature:['text','analysis','comparison','argument','research'],economics:['microeconomics','macroeconomics','trade','modelling','research'],business:['business','finance','marketing','trade','research'],accounting:['accounting','finance','business','modelling'],history:['history','causation','argument','research'],geography:['geography','physical','climate','trade','fieldwork'],environment:['ecology','climate','agriculture','geography','fieldwork'],psychology:['psychology','homeostasis','society','fieldwork','research'],sociology:['society','psychology','politics','fieldwork','research'],politics:['politics','society','trade','argument','research'],philosophy:['philosophy','tok','argument','research'],religion:['religion','history','philosophy','argument'],art:['art','design','comparison','research'],design:['design','art','energy','research'],music:['music','performance','comparison','research'],drama:['performance','text','analysis','research'],film:['film','analysis','art','research'],sport:['sport','homeostasis','nutrition','fieldwork'],nutrition:['nutrition','enzymes','homeostasis','fieldwork'],agriculture:['agriculture','ecology','photosynthesis','climate','fieldwork'],tourism:['tourism','geography','business','climate'],digital:['networks','society','politics','research'],tok:['tok','philosophy','history','research'],ee:['research','argument','fieldwork','history'],cas:['cas','research','society'],global:['politics','climate','trade','research','argument'],marine:['ecology','climate','cells','fieldwork']
};
function family(name){const n=name.toLowerCase();for(const[pattern,key]of [[/account/,'accounting'],[/agricultur/,'agriculture'],[/design.*technology/,'design'],[/art|design/,'art'],[/biolog/,'biology'],[/business|commerce|enterprise/,'business'],[/chemistry/,'chemistry'],[/computer/,'computing'],[/communication technology/,'ict'],[/drama/,'drama'],[/economics/,'economics'],[/environment/,'environment'],[/food|nutrition/,'nutrition'],[/geography/,'geography'],[/global perspective/,'global'],[/history|pakistan studies/,'history'],[/islam|religio/,'religion'],[/additional/,'additional'],[/mathematics/,'maths'],[/statistics/,'statistics'],[/music/,'music'],[/physical education/,'sport'],[/physics/,'physics'],[/psychology/,'psychology'],[/sociology/,'sociology'],[/marine/,'marine'],[/science/,'science'],[/tourism/,'tourism'],[/literature/,'literature'],[/first language/,'english']])if(pattern.test(n))return key;return'language';}
